    std::vector<unsigned char>code=File(argv[1]),reference=File(argv[2]);Fixture f;Lights lights(f);ReadRequest r;Fill(r,5);Cell cell;Hr(cell.Upload(f.d.p,r),"upload");r.Clear();Relighter relight;Hr(relight.Init(f.d.p,&code[0],code.size(),256,CellBytes(5)),"initialize");Com<ID3D11Texture2D>out;Texture(f,256,DXGI_FORMAT_R8G8B8A8_UNORM,D3D11_BIND_SHADER_RESOURCE|D3D11_BIND_RENDER_TARGET|D3D11_BIND_UNORDERED_ACCESS,out);Uniforms u=Values(256);Hr(relight.Render(cell,u,lights.views,lights.samplers,out.p),"day");std::vector<unsigned char>day=Readback(f,out.p);Check(day[0]>0&&day[3]==255,"visible coverage");Com<ID3D11Texture2D>oracle;Texture(f,256,DXGI_FORMAT_R8G8B8A8_UNORM,D3D11_BIND_UNORDERED_ACCESS,oracle);Oracle(f,reference,lights,u,oracle.p);std::vector<unsigned char>native=Readback(f,oracle.p);unsigned maxDelta=0;for(size_t i=0;i<day.size();++i){unsigned delta=unsigned(std::abs(int(day[i])-int(native[i])));if(delta>maxDelta)maxDelta=delta;}std::printf("delta=%u atlas=%u,%u,%u,%u native=%u,%u,%u,%u\n",maxDelta,day[0],day[1],day[2],day[3],native[0],native[1],native[2],native[3]);Check(maxDelta<=1,"actual SunProbe/native-BRDF reference parity");StateTest(f,relight,cell,lights,u,out.p,code);u.referenceSide[0]=10;u.worldOffset[0]=10;Hr(relight.Render(cell,u,lights.views,lights.samplers,out.p),"paired reference offset");Check(Readback(f,out.p)==day,"paired reference and offset preserve spatial native ambient UV");u=Values(256);
    u.sunColour[3]=0;u.sunDirection[1]=-.95f;Hr(relight.Render(cell,u,lights.views,lights.samplers,out.p),"night");std::vector<unsigned char>night=Readback(f,out.p);Check(night[0]<day[0]&&night[0]>0,"night native IBL");u=Values(256);u.exposure[0]=.25f;Hr(relight.Render(cell,u,lights.views,lights.samplers,out.p),"exposure");Check(Readback(f,out.p)[0]<day[0],"native exposure key");u=Values(256);
    Com<ID3D11ShaderResourceView>ov;Hr(f.d.p->CreateShaderResourceView(out.p,NULL,&ov.p),"output view");for(unsigned s=0;s<6;++s){switch(s){case 0:f.c.p->VSSetShaderResources(127,1,&ov.p);break;case 1:f.c.p->HSSetShaderResources(127,1,&ov.p);break;case 2:f.c.p->DSSetShaderResources(127,1,&ov.p);break;case 3:f.c.p->GSSetShaderResources(127,1,&ov.p);break;case 4:f.c.p->PSSetShaderResources(127,1,&ov.p);break;default:f.c.p->CSSetShaderResources(127,1,&ov.p);}AtlasViewTest::ContextFixture beforeRead(f.c.p);Hr(relight.Render(cell,u,lights.views,lights.samplers,out.p),"six-stage owned read output update");AtlasViewTest::ContextFixture afterRead(f.c.p);Check(beforeRead.Equal(afterRead),"owned output SRV all-stage exact restoration");Check(Bound(f.c.p,out.p),"owned output read binding restored");f.c.p->ClearState();}
    f.c.p->PSSetShaderResources(7,1,&ov.p);{AtlasViewTest::ContextFixture beforePs7(f.c.p);Hr(relight.Render(cell,u,lights.views,lights.samplers,out.p),"owned output PS7 update");AtlasViewTest::ContextFixture afterPs7(f.c.p);Check(beforePs7.Equal(afterPs7),"original output PS7 survives render");}f.c.p->ClearState();
    Com<ID3D11UnorderedAccessView>outputUav;Hr(f.d.p->CreateUnorderedAccessView(out.p,NULL,&outputUav.p),"output UAV");f.c.p->CSSetUnorderedAccessViews(0,1,&outputUav.p,NULL);{AtlasViewTest::ContextFixture beforeWrite(f.c.p);Check(FAILED(relight.Render(cell,u,lights.views,lights.samplers,out.p)),"write-bound output UAV refused");AtlasViewTest::ContextFixture afterWrite(f.c.p);Check(beforeWrite.Equal(afterWrite),"UAV refusal preserves all state");}f.c.p->ClearState();f.c.p->OMSetRenderTargetsAndUnorderedAccessViews(0,NULL,NULL,0,1,&outputUav.p,NULL);Check(FAILED(relight.Render(cell,u,lights.views,lights.samplers,out.p)),"write-bound output OM UAV refused");f.c.p->ClearState();
